-- DevBhoomi Himalayan Horizons admin portal. Run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, role text not null default 'admin' check (role='admin'), created_at timestamptz not null default now());
alter table public.admin_users enable row level security;
drop policy if exists "Admins can read own role" on public.admin_users;
create policy "Admins can read own role" on public.admin_users for select to authenticated using (user_id=(select auth.uid()));
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.admin_users where user_id=(select auth.uid()) and role='admin'); $$;
revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to authenticated;

create table if not exists public.districts (id uuid primary key default gen_random_uuid(), name text not null unique, slug text unique, division text, description text, hero_image_url text, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.destinations (id uuid primary key default gen_random_uuid(), name text not null, slug text unique, category text, district text, summary text, description text, best_time_to_visit text, latitude numeric, longitude numeric, image_url text, source_url text, verification_status text not null default 'unverified' check(verification_status in ('unverified','needs_review','verified')), last_verified_at date, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.partner_applications (id uuid primary key default gen_random_uuid(), business_name text not null, partner_type text, contact_name text not null, email text, phone text, district text, documents_verified boolean not null default false, status text not null default 'pending' check(status in ('pending','in_review','approved','rejected','needs_information')), review_note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.stays (id uuid primary key default gen_random_uuid(), name text not null, slug text unique, district text, stay_type text, description text, address text, contact_name text, contact_email text, contact_phone text, price_from numeric, currency text not null default 'INR', amenities text, image_url text, listing_verified boolean not null default false, status text not null default 'draft' check(status in ('draft','pending','approved','rejected','published')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.packages (id uuid primary key default gen_random_uuid(), title text not null, slug text unique, summary text, description text, duration_days integer, starting_price numeric, currency text not null default 'INR', max_group_size integer, itinerary text, inclusions text, exclusions text, content_verified boolean not null default false, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.bookings (id uuid primary key default gen_random_uuid(), trip_reference text not null, customer_name text not null, email text, phone text, service_type text, destination text, package_title text, travel_date date, travellers integer, quoted_total numeric, currency text not null default 'INR', availability_verified boolean not null default false, price_verified boolean not null default false, provider_reference text, status text not null default 'requested' check(status in ('requested','under_review','awaiting_provider','provider_confirmed','cancelled','completed')), admin_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.customers (id uuid primary key default gen_random_uuid(), full_name text not null, email text, phone text, preferred_language text not null default 'en', contact_consent boolean not null default false, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.reviews (id uuid primary key default gen_random_uuid(), reviewer_name text not null, destination_name text, rating integer not null check(rating between 1 and 5), title text, body text not null, status text not null default 'pending' check(status in ('pending','published','rejected','flagged')), admin_note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.enquiries (id uuid primary key default gen_random_uuid(), name text not null, email text, phone text, subject text not null, message text not null, status text not null default 'new' check(status in ('new','in_progress','waiting_for_customer','resolved','spam')), admin_note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.homepage_sections (id uuid primary key default gen_random_uuid(), section_key text not null unique, title text not null, subtitle text, body text, image_url text, cta_label text, cta_url text, sort_order integer not null default 0, is_visible boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.site_settings (id uuid primary key default gen_random_uuid(), setting_key text not null unique, value_text text, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.route_readiness (id uuid primary key default gen_random_uuid(), route_name text not null, route_code text not null unique, start_location text not null, end_location text not null, service_type text, operations_ready boolean not null default false, pricing_ready boolean not null default false, partners_ready boolean not null default false, admin_approved boolean not null default false, is_active boolean not null default false, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint route_activation_requires_signoff check(not is_active or (operations_ready and pricing_ready and partners_ready and admin_approved)));
create table if not exists public.fleet_vehicles (id uuid primary key default gen_random_uuid(), vehicle_name text not null, vehicle_type text, registration_no text, seats integer not null default 4, luggage_capacity integer, permit_verified boolean not null default false, insurance_verified boolean not null default false, is_available boolean not null default false, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.fare_rules (id uuid primary key default gen_random_uuid(), rule_name text not null, service_type text, route_code text, pricing_model text, base_fare numeric, per_km_rate numeric, per_hour_rate numeric, included_km numeric, tolls_included boolean not null default false, driver_allowance numeric, currency text not null default 'INR', is_active boolean not null default false, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.support_cases (id uuid primary key default gen_random_uuid(), case_reference text not null unique, trip_reference text, customer_name text not null, contact text, severity text not null default 'normal', category text, description text not null, status text not null default 'open' check(status in ('open','in_progress','waiting','escalated','resolved','closed')), assigned_to text, resolution_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid, actor_email text, action text not null, resource text not null, record_id text, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end; $$;
do $$ declare t text; begin foreach t in array array['districts','destinations','partner_applications','stays','packages','bookings','customers','reviews','enquiries','homepage_sections','site_settings','route_readiness','fleet_vehicles','fare_rules','support_cases'] loop execute format('drop trigger if exists set_updated_at on public.%I',t); execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()',t); end loop; end $$;
do $$ declare t text; begin foreach t in array array['districts','destinations','partner_applications','stays','packages','bookings','customers','reviews','enquiries','homepage_sections','site_settings','route_readiness','fleet_vehicles','fare_rules','support_cases','audit_logs'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists "admin full access" on public.%I',t); execute format('create policy "admin full access" on public.%I for all to authenticated using (public.is_admin()) with check (public.is_admin())',t); end loop; end $$;
insert into public.districts(name,slug,division) values ('Almora','almora','Kumaon'),('Bageshwar','bageshwar','Kumaon'),('Chamoli','chamoli','Garhwal'),('Champawat','champawat','Kumaon'),('Dehradun','dehradun','Garhwal'),('Haridwar','haridwar','Garhwal'),('Nainital','nainital','Kumaon'),('Pauri Garhwal','pauri-garhwal','Garhwal'),('Pithoragarh','pithoragarh','Kumaon'),('Rudraprayag','rudraprayag','Garhwal'),('Tehri Garhwal','tehri-garhwal','Garhwal'),('Udham Singh Nagar','udham-singh-nagar','Kumaon'),('Uttarkashi','uttarkashi','Garhwal') on conflict(name) do nothing;
